
const INDEX_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"Find and monitor student accommodation near London universities.\">\n  <meta name=\"theme-color\" content=\"#101b3f\">\n  <title>London Student Homefinder</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,650&display=swap\" rel=\"stylesheet\">\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='15' fill='%23101b3f'/%3E%3Cpath d='M12 31 32 14l20 17v20H38V38H26v13H12Z' fill='%23ff6f61'/%3E%3Ccircle cx='45' cy='19' r='6' fill='%23f6c453'/%3E%3C/svg%3E\">\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <header class=\"topbar\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"London Student Homefinder home\">\n      <span class=\"brand-mark\" aria-hidden=\"true\">⌂</span>\n      <span>London Student Homefinder</span>\n    </a>\n    <div class=\"top-status\"><span aria-hidden=\"true\"></span> TinyFish Agent → Fetch → Monitor</div>\n  </header>\n\n  <main id=\"top\">\n    <section class=\"intro\" aria-labelledby=\"page-title\">\n      <div>\n        <p class=\"eyebrow\">Your London shortlist</p>\n        <h1 id=\"page-title\">Find a place that works for <em>student life.</em></h1>\n        <p class=\"intro-copy\">Tell us where you study and what you need. TinyFish searches live rental websites, downloads each listing page and can keep checking weekly.</p>\n      </div>\n      <figure class=\"city-photo\">\n        <img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Percy%20Street%2C%20Fitzrovia%20-%20geograph.org.uk%20-%201091766.jpg\" alt=\"Terraced buildings on Percy Street in Fitzrovia, London\">\n        <figcaption>Central London, close to several university campuses. <a href=\"https://commons.wikimedia.org/wiki/File:Percy_Street,_Fitzrovia_-_geograph.org.uk_-_1091766.jpg\" target=\"_blank\" rel=\"noreferrer\">Photo source</a></figcaption>\n      </figure>\n    </section>\n\n    <section class=\"workspace\" aria-label=\"Accommodation search workspace\">\n      <form id=\"preferences-form\" class=\"form-panel\">\n        <div class=\"panel-heading\">\n          <span class=\"step-pill\">Preferences</span>\n          <p>Required fields are marked <span aria-hidden=\"true\">*</span></p>\n        </div>\n\n        <div class=\"field\">\n          <label for=\"university\">University <span aria-hidden=\"true\">*</span></label>\n          <input id=\"university\" name=\"university\" list=\"universities\" autocomplete=\"organization\" placeholder=\"e.g. University College London\" required>\n          <datalist id=\"universities\">\n            <option value=\"University College London (UCL)\"></option>\n            <option value=\"King's College London\"></option>\n            <option value=\"Imperial College London\"></option>\n            <option value=\"London School of Economics (LSE)\"></option>\n            <option value=\"Queen Mary University of London\"></option>\n            <option value=\"SOAS University of London\"></option>\n            <option value=\"University of Westminster\"></option>\n            <option value=\"City St George's, University of London\"></option>\n            <option value=\"Goldsmiths, University of London\"></option>\n            <option value=\"University of Greenwich\"></option>\n          </datalist>\n          <p class=\"field-note\">We use the university to suggest a nearby district.</p>\n        </div>\n\n        <div id=\"recommendation\" class=\"recommendation\" hidden aria-live=\"polite\">\n          <div>\n            <span class=\"recommendation-label\">Recommended district</span>\n            <strong id=\"recommended-district\">Fitzrovia</strong>\n            <p id=\"recommendation-reason\">A practical central base near campus.</p>\n          </div>\n          <div class=\"choice-row\" role=\"radiogroup\" aria-label=\"District choice\">\n            <label><input type=\"radio\" name=\"district-choice\" value=\"recommended\" checked> Use this district</label>\n            <label><input type=\"radio\" name=\"district-choice\" value=\"other\"> Choose another</label>\n          </div>\n        </div>\n\n        <div id=\"other-district-wrap\" class=\"field\" hidden>\n          <label for=\"other-district\">Preferred district <span aria-hidden=\"true\">*</span></label>\n          <input id=\"other-district\" name=\"other-district\" placeholder=\"e.g. Camden, Brixton or Stratford\">\n        </div>\n\n        <fieldset>\n          <legend>Budget <span aria-hidden=\"true\">*</span></legend>\n          <div class=\"budget-grid\">\n            <div class=\"field compact\"><label for=\"budget-min\">Minimum</label><div class=\"money-input\"><span>£</span><input id=\"budget-min\" name=\"budget-min\" inputmode=\"numeric\" min=\"0\" type=\"number\" placeholder=\"200\" required></div></div>\n            <div class=\"field compact\"><label for=\"budget-max\">Maximum</label><div class=\"money-input\"><span>£</span><input id=\"budget-max\" name=\"budget-max\" inputmode=\"numeric\" min=\"0\" type=\"number\" placeholder=\"350\" required></div></div>\n            <div class=\"field compact\"><label for=\"budget-unit\">Frequency</label><select id=\"budget-unit\" name=\"budget-unit\"><option value=\"per week\">Per week</option><option value=\"per month\">Per month</option></select></div>\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend>How would you like to live? <span aria-hidden=\"true\">*</span></legend>\n          <div class=\"option-cards\">\n            <label><input type=\"radio\" name=\"living\" value=\"Live alone\" required><span><b>Live alone</b><small>Studio or whole property</small></span></label>\n            <label><input type=\"radio\" name=\"living\" value=\"Share with others\"><span><b>Share with others</b><small>Room in a shared home</small></span></label>\n            <label><input type=\"radio\" name=\"living\" value=\"Either\"><span><b>Either</b><small>Show both kinds</small></span></label>\n          </div>\n        </fieldset>\n\n        <p id=\"form-error\" class=\"form-error\" role=\"alert\" hidden></p>\n        <button class=\"primary-button\" id=\"search-button\" type=\"submit\">Run TinyFish agents</button>\n      </form>\n\n      <aside class=\"results-panel\" aria-live=\"polite\">\n        <div id=\"empty-state\" class=\"empty-state\">\n          <div class=\"map-pin\" aria-hidden=\"true\">⌂</div>\n          <h2>Your search starts here</h2>\n          <p>Complete the preferences and we’ll prepare searches across Zoopla, Rightmove, SpareRoom and student-focused sources.</p>\n          <div class=\"source-strip\" aria-label=\"Search sources\">\n            <span>Zoopla</span><span>Rightmove</span><span>SpareRoom</span><span>OpenRent</span><span>StuRents</span><span>OnTheMarket</span>\n          </div>\n        </div>\n\n        <div id=\"results\" hidden>\n          <div class=\"results-heading\">\n            <div><p class=\"eyebrow\">Search ready</p><h2 id=\"results-title\">Homes in Fitzrovia</h2></div>\n            <span id=\"results-count\" class=\"count-badge\">6 sources</span>\n          </div>\n          <div id=\"filter-summary\" class=\"filter-summary\"></div>\n          <div id=\"agent-toolbar\" class=\"agent-toolbar\" hidden>\n            <div><span class=\"agent-pulse\" aria-hidden=\"true\"></span><strong id=\"agent-summary\">Starting browser agents…</strong></div>\n            <button id=\"stop-agents\" class=\"stop-button\" type=\"button\">Stop search</button>\n          </div>\n          <section id=\"live-browser\" class=\"live-browser\" hidden aria-label=\"Live TinyFish browser agent\">\n            <div class=\"live-browser-heading\">\n              <div><span>Live browser</span><strong id=\"live-browser-source\">TinyFish agent</strong></div>\n              <a id=\"live-browser-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">Open full view</a>\n            </div>\n            <iframe id=\"live-browser-frame\" title=\"Live TinyFish browser agent\" referrerpolicy=\"no-referrer\" allow=\"clipboard-read; clipboard-write\"></iframe>\n          </section>\n          <div id=\"source-results\" class=\"source-results\"></div>\n          <section id=\"monitor-offer\" class=\"monitor-offer\" hidden aria-labelledby=\"monitor-title\">\n            <div class=\"monitor-kicker\">After your search</div>\n            <h3 id=\"monitor-title\">Would you like weekly updates?</h3>\n            <p id=\"monitor-price-summary\">TinyFish will reuse this search’s district, living arrangement and exact price range.</p>\n            <div class=\"monitor-grid\">\n              <div class=\"field\"><label for=\"monitor-email\">Email for alerts</label><input id=\"monitor-email\" name=\"monitor-email\" type=\"email\" autocomplete=\"email\" placeholder=\"student@example.com\"></div>\n              <div class=\"field\"><label for=\"monitor-frequency\">Update frequency</label><select id=\"monitor-frequency\" name=\"monitor-frequency\"><option value=\"Weekly\" selected>Weekly</option><option value=\"Twice a week\">Twice a week</option><option value=\"Daily\">Daily</option></select></div>\n            </div>\n            <p class=\"field-note\">TinyFish manages email delivery in its dashboard. We save the address in your preference file, then link you there to confirm delivery.</p>\n            <button id=\"create-monitor\" class=\"primary-button monitor-button\" type=\"button\">Yes — create weekly monitor</button>\n            <div id=\"monitor-status\" class=\"monitor-status\" role=\"status\" hidden></div>\n          </section>\n          <div class=\"save-card\">\n            <div><strong>Download your search</strong><p>Create a PDF containing each website, listing link, price and location.</p><a class=\"stored-file-link\" href=\"/student_accommodation_preferences.md\" target=\"_blank\" rel=\"noreferrer\">View stored preferences file</a></div>\n            <div class=\"save-actions\"><button id=\"download-results-pdf\" class=\"secondary-button\" type=\"button\" disabled>Download results PDF</button><button id=\"download-preferences\" class=\"quiet-button\" type=\"button\">Save preferences</button></div>\n          </div>\n          <div id=\"pdf-status\" class=\"pdf-status\" role=\"status\" hidden></div>\n        </div>\n      </aside>\n    </section>\n  </main>\n\n  <footer>\n    <p>Always verify the landlord, tenancy terms, deposit protection and total monthly costs before paying anything.</p>\n  </footer>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n";
const STYLES = ":root {\n  --ink: #101b3f;\n  --ink-soft: #26345b;\n  --paper: #f5f7fb;\n  --white: #ffffff;\n  --coral: #ff6f61;\n  --coral-deep: #df5146;\n  --sun: #f6c453;\n  --sky: #dfe9ff;\n  --line: #d9dfeb;\n  --muted: #667085;\n  --success: #17735b;\n  --shadow: 0 24px 70px rgba(16, 27, 63, .13);\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--paper); color: var(--ink); font-family: \"DM Sans\", system-ui, sans-serif; font-size: 16px; line-height: 1.5; }\nbutton, input, select { font: inherit; }\na { color: inherit; }\n.topbar { height: 72px; padding: 0 clamp(20px, 5vw, 72px); display: flex; align-items: center; justify-content: space-between; background: var(--ink); color: white; }\n.brand { display: flex; gap: 11px; align-items: center; text-decoration: none; font-weight: 700; letter-spacing: -.02em; }\n.brand-mark { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--coral); color: var(--ink); font-size: 22px; }\n.top-status { font-size: .875rem; color: #dbe2f8; }\n.top-status span { display: inline-block; width: 8px; height: 8px; margin-right: 8px; background: #72d7b4; border-radius: 50%; }\nmain { width: min(1480px, 100%); margin: auto; }\n.intro { display: grid; grid-template-columns: 1.2fr .8fr; gap: clamp(28px, 6vw, 90px); align-items: center; padding: 62px clamp(20px, 5vw, 72px) 46px; background: var(--ink); color: white; border-radius: 0 0 34px 34px; overflow: hidden; position: relative; }\n.intro:after { content: \"\"; position: absolute; width: 380px; height: 380px; right: -180px; bottom: -260px; border: 60px solid rgba(246,196,83,.16); border-radius: 50%; pointer-events: none; }\n.eyebrow { margin: 0 0 10px; color: var(--coral); text-transform: uppercase; letter-spacing: .13em; font-size: .75rem; font-weight: 700; }\nh1, h2 { font-family: \"Fraunces\", Georgia, serif; }\nh1 { max-width: 760px; margin: 0; font-size: clamp(2.65rem, 6vw, 5.3rem); line-height: .99; letter-spacing: -.045em; }\nh1 em { color: var(--sun); font-style: normal; }\n.intro-copy { max-width: 650px; margin: 24px 0 0; color: #d9e0f4; font-size: 1.08rem; }\n.city-photo { margin: 0; transform: rotate(1.5deg); position: relative; z-index: 1; }\n.city-photo img { display: block; width: 100%; height: 280px; object-fit: cover; border: 8px solid white; box-shadow: 0 24px 60px rgba(0,0,0,.34); }\n.city-photo figcaption { margin: 10px 8px 0; font-size: .75rem; color: #c2cce8; }\n.workspace { display: grid; grid-template-columns: minmax(0, .93fr) minmax(420px, 1.07fr); gap: 24px; padding: 30px clamp(20px, 5vw, 72px) 72px; align-items: start; }\n.form-panel, .results-panel { background: var(--white); border: 1px solid var(--line); border-radius: 22px; box-shadow: var(--shadow); }\n.form-panel { padding: clamp(22px, 4vw, 38px); }\n.panel-heading { display: flex; justify-content: space-between; align-items: center; margin-bottom: 28px; }\n.panel-heading p { margin: 0; color: var(--muted); font-size: .8rem; }\n.step-pill { padding: 7px 12px; background: var(--sky); border-radius: 99px; font-weight: 700; font-size: .82rem; }\n.field { margin-bottom: 20px; }\nlabel, legend { font-weight: 700; font-size: .93rem; }\n.field label { display: block; margin-bottom: 7px; }\ninput, select { width: 100%; min-height: 48px; padding: 11px 13px; color: var(--ink); background: white; border: 1px solid #b9c2d4; border-radius: 10px; outline: none; }\ninput:focus, select:focus { border-color: var(--ink); box-shadow: 0 0 0 3px var(--sky); }\n.field-note { margin: 7px 0 0; color: var(--muted); font-size: .78rem; }\nfieldset { margin: 0 0 26px; padding: 0; border: 0; }\nlegend { margin-bottom: 12px; }\n.recommendation { margin: -4px 0 22px; padding: 18px; background: #fff7df; border: 1px solid #efd999; border-radius: 14px; }\n.recommendation-label { display: block; color: #7c6321; font-size: .75rem; text-transform: uppercase; letter-spacing: .08em; font-weight: 700; }\n.recommendation strong { display: block; margin: 2px 0; font-family: \"Fraunces\", Georgia, serif; font-size: 1.65rem; }\n.recommendation p { margin: 0; color: #5f5334; font-size: .86rem; }\n.choice-row { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 15px; padding-top: 14px; border-top: 1px solid #ecdcae; }\n.choice-row label { display: flex; align-items: center; gap: 7px; font-size: .84rem; cursor: pointer; }\n.choice-row input, .option-cards input { width: auto; min-height: auto; accent-color: var(--coral-deep); }\n.budget-grid { display: grid; grid-template-columns: 1fr 1fr 1.05fr; gap: 10px; }\n.compact { margin-bottom: 0; }\n.compact label { font-size: .78rem; color: var(--muted); }\n.money-input { position: relative; }\n.money-input span { position: absolute; left: 13px; top: 12px; color: var(--muted); }\n.money-input input { padding-left: 29px; }\n.option-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; }\n.option-cards label { display: flex; gap: 9px; padding: 14px 12px; border: 1px solid var(--line); border-radius: 12px; cursor: pointer; align-items: flex-start; }\n.option-cards label:has(input:checked) { border-color: var(--coral-deep); background: #fff4f2; box-shadow: inset 0 0 0 1px var(--coral-deep); }\n.option-cards b, .option-cards small { display: block; }\n.option-cards small { margin-top: 2px; color: var(--muted); font-weight: 400; line-height: 1.3; }\n.form-error { padding: 11px 13px; color: #8b2520; background: #fff0ef; border-radius: 9px; font-weight: 600; font-size: .9rem; }\n.primary-button, .secondary-button, .quiet-button { min-height: 50px; padding: 12px 18px; border: 0; border-radius: 10px; font-weight: 700; cursor: pointer; transition: transform .15s ease, background .15s ease; }\n.primary-button { width: 100%; background: var(--coral); color: #171b2c; box-shadow: 0 8px 20px rgba(223,81,70,.25); }\n.primary-button:hover, .secondary-button:hover, .quiet-button:hover { transform: translateY(-1px); }\n.primary-button:hover { background: #ff8175; }\n.results-panel { min-height: 640px; padding: clamp(22px, 4vw, 38px); position: sticky; top: 18px; }\n.empty-state { min-height: 560px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; border: 1px dashed #c5cedd; border-radius: 16px; padding: 36px; background: linear-gradient(150deg, #fff 20%, #eef3ff); }\n.map-pin { display: grid; place-items: center; width: 72px; height: 72px; border-radius: 24px 24px 24px 4px; transform: rotate(-6deg); background: var(--coral); color: var(--ink); font-size: 42px; box-shadow: 9px 11px 0 var(--sun); }\n.empty-state h2 { margin: 28px 0 8px; font-size: 2rem; }\n.empty-state p { max-width: 490px; margin: 0; color: var(--muted); }\n.source-strip { display: flex; flex-wrap: wrap; justify-content: center; gap: 7px; margin-top: 25px; }\n.source-strip span { padding: 6px 10px; border: 1px solid var(--line); border-radius: 99px; background: white; font-size: .75rem; font-weight: 600; }\n.results-heading { display: flex; justify-content: space-between; gap: 18px; align-items: end; }\n.results-heading h2 { margin: 0; font-size: clamp(1.9rem, 4vw, 2.7rem); line-height: 1.1; }\n.count-badge { padding: 7px 11px; background: var(--sky); border-radius: 99px; white-space: nowrap; font-size: .78rem; font-weight: 700; }\n.filter-summary { display: flex; flex-wrap: wrap; gap: 7px; margin: 18px 0 22px; }\n.filter-summary span { padding: 6px 10px; border: 1px solid var(--line); border-radius: 8px; color: var(--ink-soft); font-size: .77rem; }\n.source-results { display: grid; gap: 10px; }\n.agent-toolbar { display: flex; justify-content: space-between; gap: 16px; align-items: center; margin-bottom: 12px; padding: 12px 14px; border: 1px solid #b8c7eb; border-radius: 12px; background: #eef3ff; font-size: .86rem; }\n.agent-toolbar > div { display: flex; align-items: center; gap: 9px; }\n.agent-pulse { width: 10px; height: 10px; border-radius: 50%; background: var(--coral); box-shadow: 0 0 0 0 rgba(255,111,97,.45); animation: pulse 1.6s infinite; }\n.stop-button { padding: 7px 10px; border: 1px solid #aab6d1; border-radius: 8px; background: white; color: var(--ink); font-size: .78rem; font-weight: 700; cursor: pointer; }\n.live-browser { margin-bottom: 12px; overflow: hidden; border: 1px solid #26345b; border-radius: 14px; background: var(--ink); }\n.live-browser-heading { display: flex; justify-content: space-between; gap: 12px; align-items: center; padding: 12px 14px; color: white; }\n.live-browser-heading span, .live-browser-heading strong { display: block; }\n.live-browser-heading span { color: #aebadd; font-size: .72rem; text-transform: uppercase; letter-spacing: .08em; }\n.live-browser-heading a { color: var(--sun); font-size: .78rem; font-weight: 700; }\n.live-browser iframe { display: block; width: 100%; height: 300px; border: 0; background: white; }\n.source-agent { padding: 14px; border: 1px solid var(--line); border-radius: 13px; background: white; }\n.source-agent-head { display: grid; grid-template-columns: 42px 1fr auto; gap: 12px; align-items: center; }\n.source-agent-head small { display: block; color: var(--muted); margin-top: 2px; }\n.source-status { color: var(--muted); font-size: .78rem; font-weight: 700; text-align: right; }\n.source-status[data-state=\"running\"] { color: #b24c42; }\n.source-status[data-state=\"complete\"] { color: var(--success); }\n.source-status[data-state=\"error\"] { color: #9b2d28; }\n.listing-list { display: grid; gap: 8px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line); }\n.listing-card { display: grid; grid-template-columns: 1fr auto; gap: 8px 14px; padding: 12px; border-radius: 10px; background: #f7f9fd; text-decoration: none; }\n.listing-card:hover { background: #eef3ff; }\n.listing-card strong { line-height: 1.3; }\n.listing-price { color: var(--coral-deep); font-weight: 800; white-space: nowrap; }\n.listing-meta { grid-column: 1 / -1; color: var(--muted); font-size: .76rem; }\n.listing-proof { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; }\n.listing-proof span { padding: 3px 7px; border-radius: 99px; background: #e8f7f1; color: #155c49; font-size: .68rem; font-weight: 800; }\n.listing-proof span:first-child { background: var(--sky); color: var(--ink-soft); }\n.source-note { margin: 10px 0 0 54px; color: var(--muted); font-size: .78rem; }\n.source-card { display: grid; grid-template-columns: 42px 1fr auto; gap: 12px; align-items: center; padding: 14px; border: 1px solid var(--line); border-radius: 13px; text-decoration: none; transition: border .15s ease, transform .15s ease, box-shadow .15s ease; }\n.source-card:hover { border-color: var(--ink); transform: translateY(-1px); box-shadow: 0 9px 22px rgba(16,27,63,.08); }\n.source-icon { display: grid; place-items: center; width: 42px; height: 42px; background: var(--ink); color: white; border-radius: 10px; font-weight: 800; }\n.source-card strong, .source-card small { display: block; }\n.source-card small { color: var(--muted); margin-top: 2px; }\n.source-action { color: var(--coral-deep); font-size: .82rem; font-weight: 700; }\n.monitor-offer { margin-top: 20px; padding: 20px; border: 1px solid #b8c7eb; border-radius: 16px; background: linear-gradient(145deg, #eef3ff, #fff); }\n.monitor-kicker { color: var(--coral-deep); text-transform: uppercase; letter-spacing: .1em; font-size: .72rem; font-weight: 800; }\n.monitor-offer h3 { margin: 4px 0 6px; font-family: \"Fraunces\", Georgia, serif; font-size: 1.55rem; }\n.monitor-offer > p { margin: 0 0 16px; color: var(--ink-soft); font-size: .86rem; }\n.monitor-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.monitor-grid .field { margin-bottom: 4px; }\n.monitor-button { width: auto; margin-top: 16px; }\n.save-card { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-top: 20px; padding: 18px; border-radius: 14px; background: var(--ink); color: white; }\n.save-card p { margin: 4px 0 0; color: #cbd4ec; font-size: .82rem; }\n.stored-file-link { display: inline-block; margin-top: 7px; color: var(--sun); font-size: .78rem; font-weight: 700; }\n.secondary-button { background: var(--sun); color: var(--ink); white-space: nowrap; }\n.secondary-button:disabled { opacity: .5; cursor: not-allowed; transform: none; }\n.quiet-button { min-height: 42px; padding: 8px 12px; background: transparent; color: white; border: 1px solid #6d7899; white-space: nowrap; }\n.save-actions { display: grid; gap: 8px; }\n.pdf-status { margin-top: 10px; color: var(--muted); font-size: .8rem; }\n.pdf-status[data-state=\"error\"] { color: #8b2520; }\n.monitor-status { margin-top: 12px; padding: 12px 14px; background: #e8f7f1; color: #155c49; border-radius: 10px; font-size: .84rem; }\n.monitor-status[data-state=\"error\"] { background: #fff0ef; color: #8b2520; }\n.monitor-status a { font-weight: 800; }\nfooter { padding: 0 24px 42px; text-align: center; color: var(--muted); font-size: .8rem; }\n@media (max-width: 980px) {\n  .intro { grid-template-columns: 1fr; }\n  .city-photo { max-width: 620px; }\n  .workspace { grid-template-columns: 1fr; }\n  .results-panel { position: static; min-height: 0; }\n}\n@media (max-width: 620px) {\n  .topbar { height: 64px; }\n  .top-status { display: none; }\n  .intro { padding-top: 42px; border-radius: 0 0 24px 24px; }\n  .city-photo img { height: 210px; }\n  .workspace { padding-top: 18px; }\n  .budget-grid, .option-cards { grid-template-columns: 1fr; }\n  .results-heading, .save-card { align-items: flex-start; flex-direction: column; }\n  .monitor-grid { grid-template-columns: 1fr; }\n  .monitor-button { width: 100%; }\n  .secondary-button { width: 100%; }\n  .save-actions { width: 100%; }\n  .source-card, .source-agent-head { grid-template-columns: 42px 1fr; }\n  .source-action, .source-status { grid-column: 2; text-align: left; }\n  .agent-toolbar { align-items: flex-start; flex-direction: column; }\n  .stop-button { width: 100%; }\n  .live-browser iframe { height: 230px; }\n  .listing-card { grid-template-columns: 1fr; }\n  .listing-meta { grid-column: 1; }\n}\n@keyframes pulse { 70% { box-shadow: 0 0 0 8px rgba(255,111,97,0); } 100% { box-shadow: 0 0 0 0 rgba(255,111,97,0); } }\n@media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto !important; transition: none !important; } }\n";
const APP_JS = "const universityMap = [\n  { test: /ucl|university college london/i, district: \"Fitzrovia\", reason: \"Close to UCL’s main Bloomsbury campus, with easy walking access.\" },\n  { test: /king'?s college|kcl/i, district: \"Waterloo\", reason: \"Well placed for the Strand and Waterloo campuses, with strong transport links.\" },\n  { test: /imperial/i, district: \"South Kensington\", reason: \"The most convenient base for Imperial’s main campus and nearby museums.\" },\n  { test: /lse|london school of economics/i, district: \"Holborn\", reason: \"A short walk from the LSE campus around Aldwych and Lincoln’s Inn Fields.\" },\n  { test: /queen mary|qmul/i, district: \"Mile End\", reason: \"Right by Queen Mary’s main campus and connected by the Central line.\" },\n  { test: /soas/i, district: \"Bloomsbury\", reason: \"SOAS is based in Bloomsbury, close to Russell Square.\" },\n  { test: /westminster/i, district: \"Fitzrovia\", reason: \"Convenient for the Regent Street and Marylebone university buildings.\" },\n  { test: /city st george|city, university|st george/i, district: \"Clerkenwell\", reason: \"A practical base for City’s Northampton Square campus.\" },\n  { test: /goldsmith/i, district: \"New Cross\", reason: \"Goldsmiths’ campus sits in New Cross, near the Overground and National Rail.\" },\n  { test: /greenwich/i, district: \"Greenwich\", reason: \"Close to the riverside Greenwich campus and DLR connections.\" },\n  { test: /brunel/i, district: \"Uxbridge\", reason: \"The closest district to Brunel’s west London campus.\" },\n  { test: /roehampton/i, district: \"Roehampton\", reason: \"The natural local base for the University of Roehampton campus.\" },\n  { test: /london metropolitan|london met/i, district: \"Holloway\", reason: \"Close to the Holloway Road campus and Piccadilly line.\" },\n  { test: /royal college of art|rca/i, district: \"South Kensington\", reason: \"Convenient for the RCA’s Kensington campus.\" },\n  { test: /central saint martins/i, district: \"King's Cross\", reason: \"The campus is at Granary Square, beside King’s Cross and St Pancras.\" },\n  { test: /ual|university of the arts/i, district: \"King's Cross\", reason: \"A useful starting point for UAL; confirm your specific college before searching.\" }\n];\n\nconst sources = [\n  { id: \"zoopla\", name: \"Zoopla\", initials: \"Z\", note: \"Student accommodation and whole properties\" },\n  { id: \"rightmove\", name: \"Rightmove\", initials: \"R\", note: \"Flats, houses and student accommodation\" },\n  { id: \"spareroom\", name: \"SpareRoom\", initials: \"S\", note: \"Rooms and shared homes\" },\n  { id: \"openrent\", name: \"OpenRent\", initials: \"O\", note: \"Direct landlord listings\" },\n  { id: \"sturents\", name: \"StuRents\", initials: \"SR\", note: \"Student houses, flats and private halls\" },\n  { id: \"onthemarket\", name: \"OnTheMarket\", initials: \"OT\", note: \"Student properties from agents\" }\n];\n\nconst form = document.querySelector(\"#preferences-form\");\nconst university = document.querySelector(\"#university\");\nconst recommendation = document.querySelector(\"#recommendation\");\nconst recommendedDistrict = document.querySelector(\"#recommended-district\");\nconst recommendationReason = document.querySelector(\"#recommendation-reason\");\nconst otherWrap = document.querySelector(\"#other-district-wrap\");\nconst otherDistrict = document.querySelector(\"#other-district\");\nconst formError = document.querySelector(\"#form-error\");\nconst searchButton = document.querySelector(\"#search-button\");\nconst agentToolbar = document.querySelector(\"#agent-toolbar\");\nconst agentSummary = document.querySelector(\"#agent-summary\");\nconst liveBrowser = document.querySelector(\"#live-browser\");\nconst liveBrowserFrame = document.querySelector(\"#live-browser-frame\");\nconst liveBrowserLink = document.querySelector(\"#live-browser-link\");\nconst liveBrowserSource = document.querySelector(\"#live-browser-source\");\nconst stopAgents = document.querySelector(\"#stop-agents\");\nconst monitorOffer = document.querySelector(\"#monitor-offer\");\nconst monitorEmail = document.querySelector(\"#monitor-email\");\nconst monitorFrequency = document.querySelector(\"#monitor-frequency\");\nconst createMonitorButton = document.querySelector(\"#create-monitor\");\nconst monitorStatus = document.querySelector(\"#monitor-status\");\nconst downloadPdfButton = document.querySelector(\"#download-results-pdf\");\nconst pdfStatus = document.querySelector(\"#pdf-status\");\nlet currentPreferences = null;\nlet currentSearchController = null;\nlet activeRunIds = new Set();\nlet currentListings = [];\n\nfunction getRecommendation(value) {\n  return universityMap.find(item => item.test.test(value)) || { district: \"Central London\", reason: \"We could not match the campus automatically. Choose another district if you know where you want to live.\" };\n}\n\nfunction updateRecommendation() {\n  const value = university.value.trim();\n  if (value.length < 3) { recommendation.hidden = true; return; }\n  const match = getRecommendation(value);\n  recommendedDistrict.textContent = match.district;\n  recommendationReason.textContent = match.reason;\n  recommendation.hidden = false;\n}\n\nuniversity.addEventListener(\"input\", updateRecommendation);\ndocument.querySelectorAll('input[name=\"district-choice\"]').forEach(input => input.addEventListener(\"change\", event => {\n  const choosingOther = event.target.value === \"other\";\n  otherWrap.hidden = !choosingOther;\n  otherDistrict.required = choosingOther;\n  if (choosingOther) otherDistrict.focus();\n}));\n\nfunction getPreferences() {\n  const data = new FormData(form);\n  const choice = data.get(\"district-choice\") || \"recommended\";\n  const recommended = getRecommendation(data.get(\"university\") || \"\").district;\n  return {\n    university: String(data.get(\"university\") || \"\").trim(),\n    recommendedDistrict: recommended,\n    district: choice === \"other\" ? String(data.get(\"other-district\") || \"\").trim() : recommended,\n    budgetMin: Number(data.get(\"budget-min\")), budgetMax: Number(data.get(\"budget-max\")),\n    budgetUnit: String(data.get(\"budget-unit\")), living: String(data.get(\"living\") || \"\"),\n    email: monitorEmail.value.trim(), frequency: monitorFrequency.value\n  };\n}\n\nfunction validatePreferences(prefs) {\n  if (!prefs.university || !prefs.district || !prefs.living) return \"Please complete the university, district and living-arrangement questions.\";\n  if (!Number.isFinite(prefs.budgetMin) || !Number.isFinite(prefs.budgetMax) || prefs.budgetMin < 0 || prefs.budgetMax <= 0) return \"Please enter a valid minimum and maximum budget.\";\n  if (prefs.budgetMin > prefs.budgetMax) return \"Your minimum budget cannot be higher than your maximum.\";\n  return \"\";\n}\n\nfunction prepareResults(prefs) {\n  document.querySelector(\"#empty-state\").hidden = true;\n  document.querySelector(\"#results\").hidden = false;\n  document.querySelector(\"#results-title\").textContent = `Homes in ${prefs.district}`;\n  document.querySelector(\"#filter-summary\").innerHTML = [prefs.university, `£${prefs.budgetMin.toLocaleString()}–£${prefs.budgetMax.toLocaleString()} ${prefs.budgetUnit}`, prefs.living].map(item => `<span>${escapeHtml(item)}</span>`).join(\"\");\n  document.querySelector(\"#source-results\").innerHTML = sources.map(source => `\n    <section class=\"source-agent\" id=\"source-${source.id}\">\n      <div class=\"source-agent-head\"><span class=\"source-icon\">${source.initials}</span><span><strong>${source.name}</strong><small>${source.note}</small></span><span class=\"source-status\" data-state=\"waiting\">Waiting</span></div>\n      <p class=\"source-note\">The browser agent will apply your district, budget and household preferences.</p><div class=\"listing-list\" hidden></div>\n    </section>`).join(\"\");\n  monitorOffer.hidden = true;\n  monitorStatus.hidden = true;\n  pdfStatus.hidden = true;\n  currentListings = [];\n  downloadPdfButton.disabled = true;\n  createMonitorButton.disabled = false;\n  createMonitorButton.textContent = monitorFrequency.value === \"Weekly\" ? \"Yes — create weekly monitor\" : \"Create TinyFish monitor\";\n  document.querySelector(\"#monitor-price-summary\").textContent = `TinyFish will only monitor ${prefs.district} for ${prefs.living.toLowerCase()} priced £${prefs.budgetMin.toLocaleString()}–£${prefs.budgetMax.toLocaleString()} ${prefs.budgetUnit}.`;\n  document.querySelector(\"#results\").scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n}\n\nform.addEventListener(\"submit\", async event => {\n  event.preventDefault(); updateRecommendation();\n  const prefs = getPreferences(); const error = validatePreferences(prefs);\n  formError.hidden = !error; formError.textContent = error;\n  if (error) return;\n  currentPreferences = prefs; prepareResults(prefs); await runAllAgents(prefs);\n});\n\nasync function runAllAgents(prefs) {\n  if (currentSearchController) currentSearchController.abort();\n  currentSearchController = new AbortController(); activeRunIds = new Set();\n  agentToolbar.hidden = false; stopAgents.hidden = false; liveBrowser.hidden = true; searchButton.disabled = true; searchButton.textContent = \"Agents searching…\";\n  let completed = 0; let found = 0; agentSummary.textContent = `0 of ${sources.length} sources complete`;\n  for (let index = 0; index < sources.length; index += 2) {\n    if (currentSearchController.signal.aborted) break;\n    const results = await Promise.all(sources.slice(index, index + 2).map(source => runSourceAgent(source, prefs, currentSearchController.signal)));\n    completed += results.length; found += results.reduce((total, result) => total + result, 0);\n    agentSummary.textContent = `${completed} of ${sources.length} sources complete · ${found} listings found`;\n  }\n  searchButton.disabled = false; searchButton.textContent = \"Run TinyFish agents again\";\n  agentSummary.textContent = currentSearchController.signal.aborted ? `Search stopped · ${found} listings kept` : `Search complete · ${found} listings found`;\n  stopAgents.hidden = true;\n  monitorOffer.hidden = false;\n}\n\nasync function runSourceAgent(source, prefs, signal) {\n  const root = document.querySelector(`#source-${source.id}`); const status = root.querySelector(\".source-status\"); const note = root.querySelector(\".source-note\"); const list = root.querySelector(\".listing-list\");\n  status.dataset.state = \"running\"; status.textContent = \"Starting agent\";\n  try {\n    const response = await fetch(\"/api/agent/search\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ source: source.id, preferences: prefs }), signal });\n    if (!response.ok) throw new Error(await readError(response));\n    if (!response.body) throw new Error(\"The browser-agent stream was unavailable.\");\n    const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = \"\"; let listingCount = 0;\n    while (true) {\n      const { value, done } = await reader.read(); if (done) break;\n      buffer += decoder.decode(value, { stream: true });\n      const blocks = buffer.split(/\\r?\\n\\r?\\n/); buffer = blocks.pop() || \"\";\n      for (const block of blocks) {\n        const data = block.split(/\\r?\\n/).filter(line => line.startsWith(\"data:\")).map(line => line.slice(5).trim()).join(\"\\n\");\n        if (!data) continue;\n        let event; try { event = JSON.parse(data); } catch { continue; }\n        if (event.type === \"STARTED\") { activeRunIds.add(event.run_id); status.textContent = \"Browser running\"; }\n        else if (event.type === \"STREAMING_URL\") showLiveBrowser(source.name, event.streaming_url);\n        else if (event.type === \"PROGRESS\") { status.textContent = \"Searching\"; note.textContent = event.purpose || \"The agent is checking listings and prices.\"; }\n        else if (event.type === \"COMPLETE\") {\n          if (event.run_id) activeRunIds.delete(event.run_id);\n          if (event.status !== \"COMPLETED\") throw new Error(event.error?.message || \"The agent could not finish this site.\");\n          const result = normalizeResult(event.result ?? event.resultJson ?? event.result_json);\n          const candidates = result.listings || [];\n          status.textContent = candidates.length ? \"Fetching pages\" : \"No matches\";\n          note.textContent = candidates.length ? `TinyFish Fetch is downloading ${candidates.length} listing page${candidates.length === 1 ? \"\" : \"s\"}…` : (result.search_notes || \"No matching listings were returned.\");\n          const fetchedListings = candidates.length ? await fetchListingPages(source, candidates, prefs, signal) : [];\n          currentListings.push(...fetchedListings.filter(item => item.fetch_downloaded).map(item => ({ ...item, source: source.name })));\n          downloadPdfButton.disabled = currentListings.length === 0;\n          listingCount = renderListings(list, fetchedListings, source.name);\n          const fetchedCount = fetchedListings.filter(item => item.fetch_downloaded).length;\n          note.textContent = listingCount ? `${fetchedCount} listing page${fetchedCount === 1 ? \"\" : \"s\"} downloaded with TinyFish Fetch. Prices and locations were extracted by the TinyFish browser agent.` : (result.search_notes || \"No in-budget listings with verified prices were returned.\");\n          status.dataset.state = \"complete\"; status.textContent = `${listingCount} found`;\n        }\n      }\n    }\n    return listingCount;\n  } catch (error) {\n    if (signal.aborted) { status.textContent = \"Stopped\"; note.textContent = \"This search was stopped.\"; }\n    else { status.dataset.state = \"error\"; status.textContent = \"Needs attention\"; note.textContent = error.message || \"The agent could not search this source.\"; }\n    return 0;\n  }\n}\n\nfunction normalizeResult(value) { if (!value) return { listings: [] }; if (typeof value === \"string\") { try { return JSON.parse(value); } catch { return { listings: [], search_notes: value }; } } return value; }\n\nfunction weeklyBudgetRange(prefs) {\n  return prefs.budgetUnit === \"per month\"\n    ? { min: prefs.budgetMin * 12 / 52, max: prefs.budgetMax * 12 / 52 }\n    : { min: prefs.budgetMin, max: prefs.budgetMax };\n}\n\nasync function fetchListingPages(source, listings, prefs, signal) {\n  try {\n    const response = await fetch(\"/api/fetch/listings\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ source: source.id, listings, preferences: prefs }), signal });\n    if (!response.ok) throw new Error(await readError(response));\n    const data = await response.json();\n    return Array.isArray(data.listings) ? data.listings : listings;\n  } catch (error) {\n    if (signal.aborted) throw error;\n    return listings.map(item => ({ ...item, fetch_downloaded: false, fetch_error: error.message || \"TinyFish Fetch could not download this page.\" }));\n  }\n}\n\nfunction renderListings(container, listings, sourceName) {\n  const range = weeklyBudgetRange(currentPreferences);\n  const valid = listings.filter(item => item && item.url && item.title && Number.isFinite(Number(item.weekly_price_gbp)) && Number(item.weekly_price_gbp) >= range.min && Number(item.weekly_price_gbp) <= range.max); container.hidden = !valid.length;\n  container.innerHTML = valid.map(item => { const price = item.displayed_price || `£${Math.round(item.weekly_price_gbp)} pw`; const details = [item.accommodation_type, item.bills_included, item.available_from].filter(Boolean).join(\" · \"); const fetchLabel = item.fetch_downloaded ? \"Downloaded with TinyFish Fetch\" : \"Agent result — open to verify\"; return `<a class=\"listing-card\" href=\"${safeUrl(item.url)}\" target=\"_blank\" rel=\"noreferrer\"><strong>${escapeHtml(item.title)}</strong><span class=\"listing-price\">${escapeHtml(price)}</span><span class=\"listing-meta\"><b>Location:</b> ${escapeHtml(item.location || \"See listing\")}${details ? ` · ${escapeHtml(details)}` : \"\"}</span><span class=\"listing-proof\"><span>${escapeHtml(sourceName)}</span><span>${escapeHtml(fetchLabel)}</span></span></a>`; }).join(\"\");\n  return valid.length;\n}\n\nfunction showLiveBrowser(sourceName, url) { if (!url || !/^https:\\/\\//i.test(url)) return; liveBrowser.hidden = false; liveBrowserSource.textContent = sourceName; liveBrowserFrame.src = url; liveBrowserLink.href = url; }\nasync function readError(response) { try { const data = await response.json(); return data.error?.message || data.message || `Agent request failed (${response.status}).`; } catch { return `Agent request failed (${response.status}).`; } }\n\nstopAgents.addEventListener(\"click\", async () => {\n  if (currentSearchController) currentSearchController.abort();\n  const runIds = [...activeRunIds]; activeRunIds.clear();\n  await Promise.allSettled(runIds.map(runId => fetch(\"/api/agent/cancel\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ runId }) })));\n});\n\ncreateMonitorButton.addEventListener(\"click\", async () => {\n  if (!currentPreferences) return;\n  const email = monitorEmail.value.trim();\n  if (!email || !monitorEmail.checkValidity()) {\n    monitorStatus.hidden = false; monitorStatus.dataset.state = \"error\"; monitorStatus.textContent = \"Enter a valid email address for your saved alert preference.\"; monitorEmail.focus(); return;\n  }\n  currentPreferences.email = email;\n  currentPreferences.frequency = monitorFrequency.value;\n  createMonitorButton.disabled = true; createMonitorButton.textContent = \"Creating monitor…\";\n  monitorStatus.hidden = false; monitorStatus.dataset.state = \"\"; monitorStatus.textContent = \"Creating a TinyFish topic monitor and its first baseline check…\";\n  try {\n    const response = await fetch(\"/api/monitor/create\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ preferences: currentPreferences }) });\n    if (!response.ok) throw new Error(await readError(response));\n    const data = await response.json();\n    monitorStatus.innerHTML = `Monitor created for <strong>${escapeHtml(currentPreferences.frequency.toLowerCase())}</strong> checks using the same price range. To receive emails, <a href=\"${safeUrl(data.dashboard_url)}\" target=\"_blank\" rel=\"noreferrer\">confirm delivery in TinyFish</a>.`;\n    createMonitorButton.textContent = \"Monitor created\";\n  } catch (error) {\n    monitorStatus.dataset.state = \"error\"; monitorStatus.textContent = error.message || \"The monitor could not be created.\";\n    createMonitorButton.disabled = false; createMonitorButton.textContent = monitorFrequency.value === \"Weekly\" ? \"Yes — create weekly monitor\" : \"Create TinyFish monitor\";\n  }\n});\n\nmonitorFrequency.addEventListener(\"change\", () => {\n  if (!createMonitorButton.disabled) createMonitorButton.textContent = monitorFrequency.value === \"Weekly\" ? \"Yes — create weekly monitor\" : \"Create TinyFish monitor\";\n});\n\ndownloadPdfButton.addEventListener(\"click\", async () => {\n  if (!currentPreferences || !currentListings.length) return;\n  downloadPdfButton.disabled = true; pdfStatus.hidden = false; pdfStatus.dataset.state = \"\"; pdfStatus.textContent = \"Creating your PDF from TinyFish Fetch results…\";\n  try {\n    const response = await fetch(\"/api/export/pdf\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ preferences: currentPreferences, listings: currentListings }) });\n    if (!response.ok) throw new Error(await readError(response));\n    const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement(\"a\");\n    link.href = url; link.download = \"student_accommodation_results.pdf\"; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);\n    pdfStatus.textContent = `PDF created with ${currentListings.length} TinyFish-downloaded listing${currentListings.length === 1 ? \"\" : \"s\"}.`;\n  } catch (error) {\n    pdfStatus.dataset.state = \"error\"; pdfStatus.textContent = error.message || \"The PDF could not be created.\";\n  } finally { downloadPdfButton.disabled = currentListings.length === 0; }\n});\n\nfunction preferencesMarkdown(prefs) {\n  const created = new Intl.DateTimeFormat(\"en-GB\", { dateStyle: \"long\", timeStyle: \"short\", timeZone: \"Europe/London\" }).format(new Date());\n  return `# Student accommodation preferences\\n\\nSaved: ${created} (London time)\\n\\n## Location\\n\\n- University: ${prefs.university}\\n- Recommended district: ${prefs.recommendedDistrict}\\n- Chosen district: ${prefs.district}\\n\\n## Budget and household\\n\\n- Budget: £${prefs.budgetMin.toLocaleString()}–£${prefs.budgetMax.toLocaleString()} ${prefs.budgetUnit}\\n- Living arrangement: ${prefs.living}\\n\\n## Monitoring\\n\\n- Email: ${prefs.email || \"Not provided\"}\\n- Frequency: ${prefs.frequency}\\n\\n## Search sources\\n\\n- Zoopla\\n- Rightmove\\n- SpareRoom\\n- OpenRent\\n- StuRents\\n- OnTheMarket\\n\\n## Safety reminder\\n\\nVerify the landlord, tenancy terms, deposit protection, bills and total move-in cost before making a payment.\\n`;\n}\n\ndocument.querySelector(\"#download-preferences\").addEventListener(\"click\", () => { if (!currentPreferences) return; const blob = new Blob([preferencesMarkdown(currentPreferences)], { type: \"text/markdown;charset=utf-8\" }); const url = URL.createObjectURL(blob); const link = document.createElement(\"a\"); link.href = url; link.download = \"student_accommodation_preferences.md\"; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); });\n\nfunction escapeHtml(value) { return String(value).replace(/[&<>'\"]/g, character => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", \"'\": \"&#39;\", '\"': \"&quot;\" })[character]); }\nfunction safeUrl(value) { try { const url = new URL(value); return url.protocol === \"https:\" || url.protocol === \"http:\" ? escapeHtml(url.href) : \"#\"; } catch { return \"#\"; } }\n\nfunction registerWebMcpTools() {\n  const context = document.modelContext; if (!context?.registerTool) return;\n  const schema = { type: \"object\", properties: { university: { type: \"string\" }, recommendedDistrict: { type: \"string\" }, district: { type: \"string\" }, budgetMin: { type: \"number\" }, budgetMax: { type: \"number\" }, budgetUnit: { enum: [\"per week\", \"per month\"] }, living: { enum: [\"Live alone\", \"Share with others\", \"Either\"] }, email: { type: \"string\" }, frequency: { enum: [\"Daily\", \"Twice a week\", \"Weekly\"] } }, required: [\"university\", \"district\", \"budgetMin\", \"budgetMax\", \"budgetUnit\", \"living\"], additionalProperties: false };\n  context.registerTool({ name: \"set_student_accommodation_preferences\", title: \"Set accommodation preferences\", description: \"Fill the visible accommodation form and start TinyFish browser-agent searches.\", inputSchema: schema, annotations: { readOnlyHint: false, untrustedContentHint: false }, execute(input) { university.value = input.university; updateRecommendation(); const isRecommended = input.district === input.recommendedDistrict; document.querySelector(`input[name=\"district-choice\"][value=\"${isRecommended ? \"recommended\" : \"other\"}\"]`).click(); otherDistrict.value = isRecommended ? \"\" : input.district; document.querySelector(\"#budget-min\").value = input.budgetMin; document.querySelector(\"#budget-max\").value = input.budgetMax; document.querySelector(\"#budget-unit\").value = input.budgetUnit; document.querySelector(`input[name=\"living\"][value=\"${input.living}\"]`).click(); monitorEmail.value = input.email || \"\"; monitorFrequency.value = input.frequency || \"Weekly\"; form.requestSubmit(); return { status: \"agents_started\", district: input.district, sources: sources.map(source => source.name) }; } });\n  context.registerTool({ name: \"read_student_accommodation_preferences\", title: \"Read accommodation preferences\", description: \"Read the current accommodation preferences and monitoring frequency.\", inputSchema: { type: \"object\", properties: {}, additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: false }, execute() { return currentPreferences || { status: \"not_completed\" }; } });\n}\n\nregisterWebMcpTools();\n";
const PREFERENCES_MD = "# Student accommodation preferences\n\nThis preference file is stored inside the London Student Homefinder app and can also be downloaded from the results screen.\n\n## Location\n\n- University: University College London (UCL)\n- Recommended district: Fitzrovia\n- Chosen district: Fitzrovia\n\n## Budget and household\n\n- Budget: £200–£600 per week\n- Living arrangement: Share with others\n\n## Monitoring\n\n- Email: ucabdp4@ucl.ac.uk\n- Frequency: Weekly\n- Status: Create the monitor after completing a live search in the app\n\n## Search sources\n\n- Zoopla\n- Rightmove\n- SpareRoom\n- OpenRent\n- StuRents\n- OnTheMarket\n\n## Status\n\nThe TinyFish browser agent must apply the minimum and maximum price filters, verify the visible price for each listing, and exclude listings outside this range. TinyFish Fetch then downloads each accepted listing page. The app can create a PDF containing the rental website, clickable listing link, price and location. After the search, it offers a separate action to create a TinyFish topic monitor using the same district, living arrangement and exact budget.\n";

const SOURCE_URLS = {
  zoopla: district => `https://www.zoopla.co.uk/to-rent/student-accommodation/${slug(district)}/`,
  rightmove: (district, context = {}) => /^fitzrovia$/i.test(district)
    ? `https://www.rightmove.co.uk/property-to-rent/find.html?maxPrice=${encodeURIComponent(context.monthlyMax || "")}&index=0&sortType=6&channel=RENT&transactionType=LETTING&locationIdentifier=REGION%5E93764&displayLocationIdentifier=undefined`
    : `https://www.rightmove.co.uk/property-to-rent/${encodeURIComponent(district)}.html`,
  spareroom: district => `https://www.spareroom.co.uk/flatshare/london/${slug(district)}`,
  openrent: district => `https://www.openrent.co.uk/properties-to-rent/${slug(district)}`,
  sturents: () => "https://sturents.com/student-accommodation/London/",
  onthemarket: district => `https://www.onthemarket.com/student/property/${slug(district)}/`
};
const SOURCE_NAMES = { zoopla: "Zoopla", rightmove: "Rightmove", spareroom: "SpareRoom", openrent: "OpenRent", sturents: "StuRents", onthemarket: "OnTheMarket" };
const SOURCE_HOSTS = {
  zoopla: ["zoopla.co.uk"], rightmove: ["rightmove.co.uk"], spareroom: ["spareroom.co.uk"],
  openrent: ["openrent.co.uk"], sturents: ["sturents.com"], onthemarket: ["onthemarket.com"]
};

function slug(value) { return value.trim().toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function json(data, status = 200) { return new Response(JSON.stringify(data), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } }); }

async function startAgent(request, env) {
  if (!env.TINYFISH_API_KEY) return json({ error: { message: "TinyFish is not configured for this app." } }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: { message: "Invalid request body." } }, 400); }
  const source = String(body.source || "").toLowerCase();
  const prefs = body.preferences || {};
  if (!SOURCE_URLS[source]) return json({ error: { message: "Unsupported rental source." } }, 400);
  const district = String(prefs.district || "").trim().slice(0, 80);
  const university = String(prefs.university || "").trim().slice(0, 120);
  const living = String(prefs.living || "").trim().slice(0, 40);
  const unit = prefs.budgetUnit === "per month" ? "per month" : "per week";
  const min = Number(prefs.budgetMin); const max = Number(prefs.budgetMax);
  if (!district || !university || !living || !Number.isFinite(min) || !Number.isFinite(max) || min < 0 || max <= 0 || min > max) return json({ error: { message: "Complete the accommodation preferences before searching." } }, 400);
  const weeklyMin = unit === "per month" ? Math.round(min * 12 / 52) : Math.round(min);
  const weeklyMax = unit === "per month" ? Math.round(max * 12 / 52) : Math.round(max);
  const monthlyMax = unit === "per month" ? Math.round(max) : Math.round(max * 52 / 12);
  const siteName = SOURCE_NAMES[source];
  const goal = `Search ${siteName} for current accommodation in ${district}, London, suitable for a student at ${university}. PRICE IS A HARD REQUIREMENT: the user's exact budget is £${min} to £${max} ${unit}, equivalent to £${weeklyMin} to £${weeklyMax} per week. Apply the website's minimum and maximum price filters before reviewing results. The user wants: ${living}. Inspect actual result cards or listing pages and copy each displayed price from the website. Convert monthly prices to weekly using monthly × 12 ÷ 52. Only return a listing when weekly_price_gbp is between ${weeklyMin} and ${weeklyMax}, inclusive. Reject every listing outside that range or without a verifiable price. For shared accommodation, use the per-person room price—not the total property price. Return up to 8 current matches and never invent unavailable details.`;
  const output_schema = {
    type: "object",
    properties: {
      site: { type: "string" }, search_notes: { type: "string", nullable: true }, login_required: { type: "boolean" },
      listings: { type: "array", maxItems: 8, items: { type: "object", properties: {
        title: { type: "string" }, displayed_price: { type: "string" }, weekly_price_gbp: { type: "number" },
        location: { type: "string", nullable: true }, accommodation_type: { type: "string", nullable: true },
        bills_included: { type: "string", nullable: true }, available_from: { type: "string", nullable: true }, url: { type: "string" }
      }, required: ["title", "displayed_price", "weekly_price_gbp", "url"] } }
    }, required: ["site", "login_required", "listings"]
  };
  const upstream = await fetch("https://agent.tinyfish.ai/v1/automation/run-sse", {
    method: "POST",
    headers: { "X-API-Key": env.TINYFISH_API_KEY, "Content-Type": "application/json", "Accept": "text/event-stream" },
    body: JSON.stringify({ url: SOURCE_URLS[source](district, { monthlyMax }), goal, browser_profile: "stealth", api_integration: "tinyroomfinder", proxy_config: { enabled: true, country_code: "GB" }, agent_config: { max_duration_seconds: 300, cursor_style: "standard" }, capture_config: { elements: false, snapshots: false, screenshots: false, recording: false, html: false }, output_schema })
  });
  if (!upstream.ok || !upstream.body) return new Response(upstream.body || JSON.stringify({ error: { message: "TinyFish could not start." } }), { status: upstream.status || 502, headers: { "Content-Type": upstream.headers.get("Content-Type") || "application/json", "Cache-Control": "no-store" } });
  return new Response(upstream.body, { status: 200, headers: { "Content-Type": "text/event-stream; charset=utf-8", "Cache-Control": "no-store, no-transform", "X-Accel-Buffering": "no" } });
}

async function createMonitor(request, env) {
  if (!env.TINYFISH_API_KEY) return json({ error: { message: "TinyFish is not configured for this app." } }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: { message: "Invalid request body." } }, 400); }
  const prefs = body.preferences || {};
  const district = String(prefs.district || "").trim().slice(0, 80);
  const university = String(prefs.university || "").trim().slice(0, 120);
  const living = String(prefs.living || "").trim().slice(0, 40);
  const unit = prefs.budgetUnit === "per month" ? "per month" : "per week";
  const min = Number(prefs.budgetMin); const max = Number(prefs.budgetMax);
  const frequency = String(prefs.frequency || "Weekly");
  const schedules = {
    "Daily": { cron: "CRON_TZ=Europe/London 0 9 * * *", recency: 1440 },
    "Twice a week": { cron: "CRON_TZ=Europe/London 0 9 * * 1,4", recency: 5040 },
    "Weekly": { cron: "CRON_TZ=Europe/London 0 9 * * 1", recency: 10080 }
  };
  if (!district || !university || !living || !Number.isFinite(min) || !Number.isFinite(max) || min < 0 || max <= 0 || min > max || !schedules[frequency]) return json({ error: { message: "Complete a valid search and choose a monitoring frequency first." } }, 400);
  const weeklyMin = unit === "per month" ? Math.round(min * 12 / 52) : Math.round(min);
  const weeklyMax = unit === "per month" ? Math.round(max * 12 / 52) : Math.round(max);
  const domains = "(site:zoopla.co.uk OR site:rightmove.co.uk OR site:spareroom.co.uk OR site:openrent.co.uk OR site:sturents.com OR site:onthemarket.com)";
  const query = `"${district}" London student accommodation room flat to rent ${domains}`;
  const purpose = `Find newly available student accommodation in ${district}, London for a student at ${university}. Only treat a result as relevant when it matches ${living.toLowerCase()} and its verified per-person price is within the exact user budget of £${min}–£${max} ${unit} (equivalent to £${weeklyMin}–£${weeklyMax} per week). Reject results outside the range, results without a visible price, and total-property prices that do not show an in-range per-person price.`;
  const upstream = await fetch("https://agent.tinyfish.ai/v1/monitors", {
    method: "POST",
    headers: { "X-API-Key": env.TINYFISH_API_KEY, "Content-Type": "application/json", "Accept": "application/json" },
    body: JSON.stringify({ type: "search", name: `TinyRoomFinder: ${district} £${min}–£${max} ${unit}`, config: { query, recency_minutes: schedules[frequency].recency, result_limit: 10 }, schedule_cron: schedules[frequency].cron, purpose })
  });
  let result = null;
  try { result = await upstream.json(); } catch {}
  if (!upstream.ok) return json({ error: { message: result?.error?.message || result?.message || "TinyFish could not create the monitor." } }, upstream.status || 502);
  const monitor = result?.monitor || result || {};
  return json({ monitor: { id: monitor.id || monitor.monitor_id || null, name: monitor.name || `TinyRoomFinder: ${district}`, status: monitor.status || "created", schedule_cron: monitor.schedule_cron || schedules[frequency].cron }, baseline_created: Boolean(result?.run), email_requires_dashboard: true, dashboard_url: "https://agent.tinyfish.ai/monitor" }, 201);
}

function allowedListingUrl(source, value) {
  try {
    const url = new URL(value);
    return url.protocol === "https:" && SOURCE_HOSTS[source]?.some(host => url.hostname === host || url.hostname.endsWith(`.${host}`));
  } catch { return false; }
}

async function fetchListings(request, env) {
  if (!env.TINYFISH_API_KEY) return json({ error: { message: "TinyFish is not configured for this app." } }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: { message: "Invalid request body." } }, 400); }
  const source = String(body.source || "").toLowerCase();
  const prefs = body.preferences || {};
  const candidates = Array.isArray(body.listings) ? body.listings.slice(0, 8) : [];
  if (!SOURCE_HOSTS[source] || !candidates.length) return json({ error: { message: "No supported listing pages were supplied." } }, 400);
  const listings = candidates.filter(item => item && allowedListingUrl(source, item.url)).map(item => ({
    title: String(item.title || "Listing").slice(0, 300), displayed_price: String(item.displayed_price || "").slice(0, 100),
    weekly_price_gbp: Number(item.weekly_price_gbp), location: item.location == null ? null : String(item.location).slice(0, 200),
    accommodation_type: item.accommodation_type == null ? null : String(item.accommodation_type).slice(0, 120),
    bills_included: item.bills_included == null ? null : String(item.bills_included).slice(0, 120),
    available_from: item.available_from == null ? null : String(item.available_from).slice(0, 120), url: String(item.url)
  }));
  if (!listings.length) return json({ error: { message: "The agent did not return valid listing links for this source." } }, 400);
  const district = String(prefs.district || "London").slice(0, 80);
  const min = Number(prefs.budgetMin); const max = Number(prefs.budgetMax);
  const unit = prefs.budgetUnit === "per month" ? "per month" : "per week";
  const upstream = await fetch("https://api.fetch.tinyfish.ai", {
    method: "POST",
    headers: { "X-API-Key": env.TINYFISH_API_KEY, "Content-Type": "application/json", "Accept": "application/json" },
    body: JSON.stringify({ urls: listings.map(item => item.url), format: "markdown", links: false, image_links: false, ttl: 0, purpose: `Download current accommodation listing details for ${district}, including the displayed price and location, to support a student rental search with a £${min}–£${max} ${unit} budget.` })
  });
  let result = null;
  try { result = await upstream.json(); } catch {}
  if (!upstream.ok) return json({ error: { message: result?.error?.message || result?.message || "TinyFish Fetch could not download the listing pages." } }, upstream.status || 502);
  const downloaded = Array.isArray(result?.results) ? result.results : [];
  const downloadedUrls = new Set();
  for (const item of downloaded) {
    if (item?.url) downloadedUrls.add(item.url);
    if (item?.final_url) downloadedUrls.add(item.final_url);
  }
  return json({ source: SOURCE_NAMES[source], listings: listings.map(item => {
    const fetched = downloaded.find(resultItem => resultItem?.url === item.url || resultItem?.final_url === item.url);
    return { ...item, fetch_downloaded: downloadedUrls.has(item.url) || Boolean(fetched), fetch_title: fetched?.title || null };
  }), fetched_count: downloaded.length, errors: Array.isArray(result?.errors) ? result.errors.length : 0 });
}

function pdfText(value) {
  return String(value ?? "").replace(/£/g, "\\243").replace(/[–—]/g, "-").replace(/[‘’]/g, "'").replace(/[“”]/g, '"').normalize("NFKD").replace(/[^ -~]/g, "").replace(/([\\()])/g, "\\$1");
}

function buildResultsPdf(listings, prefs) {
  const objects = [null, null, null, null];
  const addObject = value => { objects.push(value); return objects.length - 1; };
  const pageIds = [];
  const chunks = [];
  for (let index = 0; index < listings.length; index += 7) chunks.push(listings.slice(index, index + 7));
  chunks.forEach((pageListings, pageIndex) => {
    const commands = [
      "BT /F1 18 Tf 50 795 Td (Student accommodation results) Tj ET",
      "BT /F1 10 Tf 50 775 Td (" + pdfText(prefs.district || "London") + " | Budget: " + pdfText("£" + prefs.budgetMin + "-£" + prefs.budgetMax + " " + prefs.budgetUnit) + " | Page " + (pageIndex + 1) + " of " + chunks.length + ") Tj ET"
    ];
    const links = [];
    pageListings.forEach((item, itemIndex) => {
      const y = 735 - itemIndex * 96;
      const safeUrl = encodeURI(String(item.url));
      commands.push("BT /F1 12 Tf 50 " + y + " Td (" + pdfText((pageIndex * 7 + itemIndex + 1) + ". " + (item.source || "Rental website")) + ") Tj ET");
      commands.push("BT /F1 10 Tf 62 " + (y - 17) + " Td (Price: " + pdfText(item.displayed_price || ("£" + Math.round(item.weekly_price_gbp) + " pw")) + ") Tj ET");
      commands.push("BT /F1 10 Tf 62 " + (y - 34) + " Td (Location: " + pdfText(item.location || "See listing") + ") Tj ET");
      commands.push("BT /F1 9 Tf 62 " + (y - 51) + " Td (Listing: " + pdfText(safeUrl.slice(0, 105)) + ") Tj ET");
      links.push({ url: safeUrl, y: y - 53 });
    });
    const stream = commands.join("\n");
    const contentId = addObject("<< /Length " + stream.length + " >>\nstream\n" + stream + "\nendstream");
    const annotationIds = links.map(link => addObject("<< /Type /Annot /Subtype /Link /Rect [60 " + link.y + " 545 " + (link.y + 13) + "] /Border [0 0 0] /A << /S /URI /URI (" + pdfText(link.url) + ") >> >>"));
    const pageId = addObject("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents " + contentId + " 0 R /Annots [" + annotationIds.map(id => id + " 0 R").join(" ") + "] >>");
    pageIds.push(pageId);
  });
  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";
  objects[2] = "<< /Type /Pages /Count " + pageIds.length + " /Kids [" + pageIds.map(id => id + " 0 R").join(" ") + "] >>";
  objects[3] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>";
  let pdf = "%PDF-1.4\n% TinyRoomFinder\n";
  const offsets = [0];
  for (let id = 1; id < objects.length; id += 1) { offsets[id] = pdf.length; pdf += id + " 0 obj\n" + objects[id] + "\nendobj\n"; }
  const xref = pdf.length;
  pdf += "xref\n0 " + objects.length + "\n0000000000 65535 f \n";
  for (let id = 1; id < objects.length; id += 1) pdf += String(offsets[id]).padStart(10, "0") + " 00000 n \n";
  pdf += "trailer\n<< /Size " + objects.length + " /Root 1 0 R >>\nstartxref\n" + xref + "\n%%EOF";
  return new TextEncoder().encode(pdf);
}

async function exportPdf(request) {
  let body;
  try { body = await request.json(); } catch { return json({ error: { message: "Invalid request body." } }, 400); }
  const prefs = body.preferences || {};
  const min = Number(prefs.budgetMin); const max = Number(prefs.budgetMax);
  const weeklyMin = prefs.budgetUnit === "per month" ? min * 12 / 52 : min;
  const weeklyMax = prefs.budgetUnit === "per month" ? max * 12 / 52 : max;
  const allHosts = Object.values(SOURCE_HOSTS).flat();
  const listings = (Array.isArray(body.listings) ? body.listings : []).slice(0, 48).filter(item => {
    if (!item?.fetch_downloaded || !Number.isFinite(Number(item.weekly_price_gbp)) || Number(item.weekly_price_gbp) < weeklyMin || Number(item.weekly_price_gbp) > weeklyMax) return false;
    try { const url = new URL(item.url); return url.protocol === "https:" && allHosts.some(host => url.hostname === host || url.hostname.endsWith(`.${host}`)); } catch { return false; }
  });
  if (!listings.length) return json({ error: { message: "No in-budget TinyFish Fetch results are available for the PDF yet." } }, 400);
  const pdf = buildResultsPdf(listings, prefs);
  return new Response(pdf, { headers: { "Content-Type": "application/pdf", "Content-Disposition": "attachment; filename=student_accommodation_results.pdf", "Cache-Control": "no-store" } });
}

async function cancelAgent(request, env) {
  if (!env.TINYFISH_API_KEY) return json({ error: { message: "TinyFish is not configured." } }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: { message: "Invalid request body." } }, 400); }
  const runId = String(body.runId || "");
  if (!/^[a-zA-Z0-9_-]{8,100}$/.test(runId)) return json({ error: { message: "Invalid run ID." } }, 400);
  const upstream = await fetch(`https://agent.tinyfish.ai/v1/runs/${encodeURIComponent(runId)}/cancel`, { method: "POST", headers: { "X-API-Key": env.TINYFISH_API_KEY } });
  return new Response(upstream.body, { status: upstream.status, headers: { "Content-Type": upstream.headers.get("Content-Type") || "application/json", "Cache-Control": "no-store" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === "POST" && url.pathname === "/api/agent/search") return startAgent(request, env);
    if (request.method === "POST" && url.pathname === "/api/agent/cancel") return cancelAgent(request, env);
    if (request.method === "POST" && url.pathname === "/api/fetch/listings") return fetchListings(request, env);
    if (request.method === "POST" && url.pathname === "/api/monitor/create") return createMonitor(request, env);
    if (request.method === "POST" && url.pathname === "/api/export/pdf") return exportPdf(request);
    if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", { status: 405, headers: { Allow: "GET, HEAD, POST" } });
    if (url.pathname === "/" || url.pathname === "/index.html") return new Response(request.method === "HEAD" ? null : INDEX_HTML, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache" } });
    if (url.pathname === "/styles.css") return new Response(request.method === "HEAD" ? null : STYLES, { headers: { "Content-Type": "text/css; charset=utf-8", "Cache-Control": "public, max-age=300" } });
    if (url.pathname === "/app.js") return new Response(request.method === "HEAD" ? null : APP_JS, { headers: { "Content-Type": "text/javascript; charset=utf-8", "Cache-Control": "public, max-age=300" } });
    if (url.pathname === "/student_accommodation_preferences.md" || url.pathname === "/student_accomodation_preferences.md") return new Response(request.method === "HEAD" ? null : PREFERENCES_MD, { headers: { "Content-Type": "text/markdown; charset=utf-8", "Content-Disposition": "inline; filename=student_accommodation_preferences.md", "Cache-Control": "no-cache" } });
    return new Response("Not found", { status: 404 });
  }
};
